                super().__init__()

            def test_should_not_run(self):
                assert True

        class TestWithCustomNew:
            def __new__(cls, *args, **kwargs):
                return super().__new__(cls, *args, **kwargs)

            def test_should_not_run(self):
                assert True

        class TestNormal:
            def test_should_run(self):
                assert True
    """
    )

    result = testdir.runpytest("-W", "always::pytest.PytestCollectionWarning", "-v")

