    ])

    # Check that only TestNormal.test_should_run was collected and passed
    result.stdout.fnmatch_lines([
        "*test_class_collection.py::TestNormal::test_should_run PASSED*"
    ])

    result.assert_outcomes(passed=1, warnings=2)
