        result = metafunc._resolve_arg_value_types(["arg1", "arg2", "arg3"], False)
        assert result == {"arg1": "funcargs", "arg2": "funcargs", "arg3": "funcargs"}

        # Test with indirect=True (all args as params)
        result = metafunc._resolve_arg_value_types(["arg1", "arg2", "arg3"], True)
        assert result == {"arg1": "params", "arg2": "params", "arg3": "params"}

        # Test with indirect as list of some args
        result = metafunc._resolve_arg_value_types(["arg1", "arg2", "arg3"], ["arg1", "arg3"])
        assert result == {"arg1": "params", "arg2": "funcargs", "arg3": "params"}

        # Test with indirect as tuple
        result = metafunc._resolve_arg_value_types(["arg1", "arg2", "arg3"], ("arg2",))
        assert result == {"arg1": "funcargs", "arg2": "params", "arg3": "funcargs"}

        # Test with indirect containing non-existent arg
        with pytest.raises(Exception) as excinfo:
            metafunc._resolve_arg_value_types(["arg1", "arg2"], ["arg3"])
        assert "indirect fixture 'arg3' doesn't exist" in str(excinfo.value)

        # Test with empty argnames
        result = metafunc._resolve_arg_value_types([], False)
        assert result == {}

        # Test with single arg
        result = metafunc._resolve_arg_value_types(["single_arg"], True)
        assert result == {"single_arg": "params"}
