def test_parametrize_scope(pytester: Pytester) -> None:
    """Test that parametrize correctly determines and sets the scope in various scenarios."""
    # Test cases for valid scopes
    pytester.makeconftest("""
        def pytest_collection_modifyitems(items):
            for item in items:
                if item.name.startswith("test_scope"):
                    callspec = item.callspec
                    if "narrowest" in item.name:
                        # All arguments are fixtures, should use function scope (index 0)
                        assert callspec._arg2scopenum["func_fixture"] == 0
                        assert callspec._arg2scopenum["class_fixture"] == 0
                    elif "explicit" in item.name:
                        # Explicit class scope, should use class scope (index 1)
                        assert callspec._arg2scopenum["func_fixture"] == 1
                    elif "mixed" in item.name:
                        # Some arguments are not fixtures, should use function scope (index 0)
                        assert callspec._arg2scopenum["func_fixture"] == 0
                        assert "non_fixture" not in callspec._arg2scopenum
    """)

    pytester.makepyfile("""
        import pytest

        @pytest.fixture(scope="function")
        def func_fixture():
            return 1

        @pytest.fixture(scope="class")
        def class_fixture():
            return 2

        def test_scope_narrowest(metafunc):
            pass

        def test_scope_explicit(metafunc):
            pass

        def test_scope_mixed(metafunc):
            pass

        def pytest_generate_tests(metafunc):
            if metafunc.function.__name__ == "test_scope_narrowest":
                metafunc.parametrize(
                    ["func_fixture", "class_fixture"],
                    [(1, 2)],
                    indirect=True
                )
            elif metafunc.function.__name__ == "test_scope_explicit":
                metafunc.parametrize(
                    ["func_fixture"],
                    [1],
                    indirect=True,
                    scope="class"
                )
            elif metafunc.function.__name__ == "test_scope_mixed":
                metafunc.parametrize(
                    ["func_fixture", "non_fixture"],
                    [(1, 2)],
                    indirect=["func_fixture"]
                )
    """)

    result = pytester.inline_run()
    result.assertoutcome(passed=3)

    # Test case for invalid scope
    pytester.makepyfile(test_invalid="""
        import pytest

        def test_invalid_scope():
            pass

        def pytest_generate_tests(metafunc):
            metafunc.parametrize(
                ["arg"],
                [1],
                scope="invalid_scope"
            )
    """)

    result = pytester.runpytest()
    result.stderr.fnmatch_lines([
        "*ValueError: scope invalid_scope for parametrize() call in test_invalid_scope is not one of session, module, class, function*"
    ])
