class LocaleRegexDescriptorTests(SimpleTestCase):
    def test_string_pattern(self):
        import re
        class MockPattern:
            regex = LocaleRegexDescriptor('_regex')
            def __init__(self, regex):
                self._regex = regex
            def _compile(self, regex):
                return re.compile(regex)

        pattern = MockPattern(r'^test/$')
        regex = pattern.regex
        self.assertIsInstance(regex, re.Pattern)
        self.assertEqual(regex.pattern, '^test/$')
        self.assertIn('regex', pattern.__dict__)
        self.assertIs(pattern.regex, pattern.__dict__['regex'])

    def test_non_string_pattern(self):
        import re
        from django.utils import translation
        class MockPattern:
            regex = LocaleRegexDescriptor('_regex')
            def __init__(self, regex):
                self._regex = regex
                self._regex_dict = {}
            def _compile(self, regex):
                return re.compile(regex)

        class LazyPattern:
            def __str__(self):
                return r'^{}/$'.format(translation.get_language())

        pattern = MockPattern(LazyPattern())

        with translation.override('en'):
            regex_en = pattern.regex
            self.assertEqual(regex_en.pattern, '^en/$')
            self.assertIn('en', pattern._regex_dict)
            self.assertIs(regex_en, pattern._regex_dict['en'])

        with translation.override('fr'):
            regex_fr = pattern.regex
            self.assertEqual(regex_fr.pattern, '^fr/$')
            self.assertIn('fr', pattern._regex_dict)
            self.assertIs(regex_fr, pattern._regex_dict['fr'])

        self.assertIn('en', pattern._regex_dict)
