            class TestForm(ModelForm):
                class Meta:
                    model = ChoiceModel
                    fields = 'name'
        self.assertIn("TestForm.Meta.fields cannot be a string", str(cm.exception))

        # Test for exclude
        with self.assertRaises(TypeError) as cm:
            class TestForm(ModelForm):
                class Meta:
                    model = ChoiceModel
                    exclude = 'name'
        self.assertIn("TestForm.Meta.exclude cannot be a string", str(cm.exception))

        # Test for localized_fields
        with self.assertRaises(TypeError) as cm:
            class TestForm(ModelForm):
                class Meta:
                    model = ChoiceModel
                    fields = '__all__'
                    localized_fields = 'name'
        self.assertIn("TestForm.Meta.localized_fields cannot be a string", str(cm.exception))

    def test_improperly_configured_without_fields_or_exclude(self):
        """Test that ImproperlyConfigured is raised when model is defined but neither fields nor exclude is defined"""
        with self.assertRaises(ImproperlyConfigured) as cm:
            class TestForm(ModelForm):
                class Meta:
                    model = ChoiceModel
        self.assertIn("Creating a ModelForm without either the 'fields' attribute or the 'exclude' attribute is prohibited", str(cm.exception))

