        @property
        def data(self):
            return self._data

    var = MockVariable(MockDaskArray())
    result = formatting.short_data_repr(var)
    assert result == "dask_array"  # single line stays unchanged

    # Test with multi-line repr exceeding 40 lines
    class MockDaskArrayLong:
        def __array_function__(self, *args, **kwargs):
            pass

        def __repr__(self):
            return "\n".join(f"line{i}" for i in range(41))

    var = MockVariable(MockDaskArrayLong())
    result = formatting.short_data_repr(var)
    assert "..." in result
    assert result.startswith("line0")
    assert result.endswith("line40")
    assert result.count("\n") + 1 == 41  # 20 front + ... + 20 back = 41 lines


def test_short_data_repr_large_internal_array():
    class MockVariable:
        def __init__(self, in_memory, size, dtype):
            self._in_memory = in_memory
            self.size = size
            self.dtype = dtype
            self._data = None  # required for internal_data access

    # Test exactly at 1e5 threshold (not in memory)
    var = MockVariable(in_memory=False, size=100000, dtype=np.float64)
    result = formatting.short_data_repr(var)
    assert result == "[100000 values with dtype=float64]"

    # Test above threshold with different dtype
    var = MockVariable(in_memory=False, size=150000, dtype=np.int32)
    result = formatting.short_data_repr(var)
    assert result == "[150000 values with dtype=int32]"

    # Test just below threshold should NOT hit this branch (but we don't test that here)
