def test_canonical_variables_extended():
    from sympy import Integral, Sum, Lambda, Product
    from sympy.abc import x, y, z, alpha, _0, _1, _2

    # Test with multiple bound variables in a single expression
    assert Integral(x*y, (x, 0, 1), (y, 0, 1)).canonical_variables == {x: _0, y: _1}

    # Test with symbols that have custom assumptions
    x_real = Symbol('x', real=True)
    assert Integral(x_real, (x_real, 0, 1)).canonical_variables == {x_real: _0}

    # Test with Greek letters
    assert Integral(alpha, (alpha, 0, 1)).canonical_variables == {alpha: _0}

    # Test with expressions that have no bound symbols
    assert (x + y).canonical_variables == {}

    # Test with expressions where bound symbols are already dummy symbols
    assert Integral(_0, (_0, 0, 1)).canonical_variables == {_0: _1}

    # Test with Lambda expressions with multiple parameters
    assert Lambda((x, y), x + y).canonical_variables == {x: _0, y: _1}

    # Test with nested expressions
    nested_integral = Integral(Integral(x*y, (x, 0, 1)), (y, 0, 1))
    assert nested_integral.canonical_variables == {x: _0, y: _1}

    # Test with Sum and Product
    assert Sum(x**2, (x, 0, 10)).canonical_variables == {x: _0}
    assert Product(x, (x, 1, 5)).canonical_variables == {x: _0}

    # Test with Lambda where bound symbol name conflicts with existing symbol
    assert Lambda(x, x + _0).canonical_variables == {x: _1}

    # Test with multiple bound variables with name conflicts
    assert Integral(x*y, (x, 0, _0), (y, 0, _1)).canonical_variables == {x: _2, y: Symbol('_3')}

    # Test with symbols that have subscripts
    x1 = Symbol('x_1')
    assert Integral(x1, (x1, 0, 1)).canonical_variables == {x1: _0}
