def test_genfunctions_with_module_and_class_level_pytest_generate_tests(testdir):
    """Test that _genfunctions correctly handles both module-level and class-level pytest_generate_tests hooks."""
    testdir.makepyfile(
        test_hooks="""
        import pytest

        values = []

        def pytest_generate_tests(metafunc):
            if 'x' in metafunc.fixturenames:
                metafunc.parametrize('x', [1])
                values.append('module')

        class TestClass:
            @classmethod
            def pytest_generate_tests(cls, metafunc):
                if 'y' in metafunc.fixturenames:
                    metafunc.parametrize('y', [2])
                    values.append('class')

            def test_combined(self, x, y):
                assert (x, y) == (1, 2)
                assert values == ['module', 'class']
        """
    )

    # Run pytest
    result = testdir.runpytest()

    # Check that the test passed
    result.assert_outcomes(passed=1)
