def test_constructor_postprocessors():
    # Define custom Basic subclasses
    class CustomArg1(Basic):
        pass

    class CustomArg2(Basic):
        pass

    class CustomBasic(Basic):
        pass

    class NewBasic(Basic):
        pass

    # Define postprocessor functions
    def postprocessor1(obj):
        return Basic(1, *obj.args)

    def postprocessor2(obj):
        return Basic(2, *obj.args)

    def postprocessor3(obj):
        # This postprocessor doesn't change the object
        return obj

    def postprocessor4(obj):
        return NewBasic(*obj.args)

    def postprocessor5a(obj):
        return Basic(5, *obj.args)

    def postprocessor5b(obj):
        return Basic(5, *obj.args)

    # Register the postprocessors
    Basic._constructor_postprocessor_mapping[CustomArg1] = {
        'CustomBasic': [postprocessor1]
    }

    Basic._constructor_postprocessor_mapping[CustomArg2] = {
        'CustomBasic': [postprocessor2, postprocessor3]
    }

    # Case 1: Single argument triggering a postprocessor
    arg1 = CustomArg1()
    obj1 = CustomBasic(arg1)
    result1 = Basic._exec_constructor_postprocessors(obj1)
    assert result1 == Basic(1, arg1)

    # Case 2: Multiple arguments triggering different postprocessors
    arg2 = CustomArg2()
    obj2 = CustomBasic(arg1, arg2)
    result2 = Basic._exec_constructor_postprocessors(obj2)
    # postprocessor1 and postprocessor2 should both be applied in that order
    # postprocessor3 doesn't change anything
    assert result2 == Basic(2, 1, arg1, arg2)

    # Case 3: No matching postprocessors
    obj3 = CustomBasic(1, 2, 3)
    result3 = Basic._exec_constructor_postprocessors(obj3)
    assert result3 == obj3

    # Case 4: Postprocessor changes the object type
    Basic._constructor_postprocessor_mapping[CustomArg1] = {
        'CustomBasic': [postprocessor1, postprocessor4]
    }

    obj4 = CustomBasic(arg1)
    result4 = Basic._exec_constructor_postprocessors(obj4)
    # postprocessor1: Basic(1, arg1)
    # postprocessor4: NewBasic(1, arg1)
    assert result4 == NewBasic(1, arg1)

    # Case 5: Argument that's not a Basic instance
    obj5 = CustomBasic(42)  # 42 is not a Basic instance
    result5 = Basic._exec_constructor_postprocessors(obj5)
    assert result5 == obj5  # No postprocessors should be applied

    # Case 6: Duplicate postprocessors (different function objects)
    Basic._constructor_postprocessor_mapping[CustomArg1] = {
        'CustomBasic': [postprocessor5a]
    }

    Basic._constructor_postprocessor_mapping[CustomArg2] = {
        'CustomBasic': [postprocessor5b]
    }

    obj6 = CustomBasic(arg1, arg2)
    result6 = Basic._exec_constructor_postprocessors(obj6)
    # Both postprocessor5a and postprocessor5b should be applied
    assert result6 == Basic(5, 5, arg1, arg2)

    # Clean up
    del Basic._constructor_postprocessor_mapping[CustomArg1]
    del Basic._constructor_postprocessor_mapping[CustomArg2]
